// One row per line item, with the invoice fields repeated on each row.
// Works with any Parser Template: the first list of objects in the result is
// treated as the line items; every plain field becomes a column.
const sourceNames = $('Read invoice files').all().map(f => f.binary?.data?.fileName);
const rows = [];

$input.all().forEach((item, i) => {
  const data = item.json.data || {};
  const header = { source_file: sourceNames[i] ?? '' };
  let lines = [];
  for (const [key, value] of Object.entries(data)) {
    if (Array.isArray(value) && value.length && typeof value[0] === 'object') {
      if (!lines.length) lines = value;
    } else if (value === null || typeof value !== 'object') {
      header[key] = value;
    }
  }
  header.request_id = item.json.request_id;

  if (!lines.length) {
    rows.push({ json: header });
    return;
  }
  for (const line of lines) {
    const row = { ...header };
    for (const [key, value] of Object.entries(line)) row[`line_${key}`] = value;
    rows.push({ json: row });
  }
});

return rows;
